"use client";
import { useState } from 'react';
import { StepIndicator } from '@/components/StepIndicator';
import { StepAccount } from '@/components/StepAccount';
import { StepProfile } from '@/components/StepProfile';
import { StepPreferences } from '@/components/StepPreferences';
import { StepComplete } from '@/components/StepComplete';

const STEPS = ['Account', 'Profile', 'Preferences', 'Done'];

export interface WizardData {
  email: string;
  password: string;
  firstName: string;
  lastName: string;
  bio: string;
  theme: string;
  notifications: boolean;
}

export default function App() {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<WizardData>({
    email: '', password: '', firstName: '', lastName: '',
    bio: '', theme: 'system', notifications: true,
  });

  const update = (patch: Partial<WizardData>) => setData(d => ({ ...d, ...patch }));
  const next = () => setStep(s => Math.min(s + 1, STEPS.length - 1));
  const back = () => setStep(s => Math.max(s - 1, 0));

  const stepProps = { data, update, onNext: next, onBack: back, isFirst: step === 0, isLast: step === STEPS.length - 2 };

  return (
    <div className="min-h-screen bg-gradient-to-br from-violet-50 to-indigo-100 flex items-center justify-center p-4">
      <div className="w-full max-w-lg bg-white rounded-3xl shadow-2xl overflow-hidden">
        {/* Header */}
        <div className="bg-gradient-to-r from-violet-600 to-indigo-600 px-8 py-6">
          <h1 className="text-2xl font-bold text-white">Get Started</h1>
          <p className="text-violet-200 text-sm mt-1">Step {step + 1} of {STEPS.length}</p>
          <div className="mt-4">
            <StepIndicator steps={STEPS} current={step} />
          </div>
        </div>
        {/* Body */}
        <div className="px-8 py-8">
          {step === 0 && <StepAccount {...stepProps} />}
          {step === 1 && <StepProfile {...stepProps} />}
          {step === 2 && <StepPreferences {...stepProps} />}
          {step === 3 && <StepComplete data={data} onRestart={() => setStep(0)} />}
        </div>
      </div>
    </div>
  );
}

