interface StepIndicatorProps { steps: string[]; current: number; }

export function StepIndicator({ steps, current }: StepIndicatorProps) {
  return (
    <div className="flex items-center gap-2">
      {steps.map((label, i) => (
        <div key={label} className="flex items-center gap-2 flex-1 last:flex-none">
          <div className={`w-7 h-7 rounded-full flex items-center justify-center text-xs font-bold flex-shrink-0 transition-all ${
            i < current ? 'bg-white text-violet-600' :
            i === current ? 'bg-white text-violet-600 ring-2 ring-white ring-offset-2 ring-offset-violet-600' :
            'bg-violet-500/40 text-violet-200'
          }`}>
            {i < current ? '✓' : i + 1}
          </div>
          {i < steps.length - 1 && <div className={`h-0.5 flex-1 rounded-full transition-all ${i < current ? 'bg-white' : 'bg-violet-500/30'}`} />}
        </div>
      ))}
    </div>
  );
}

