"use client";
import { useState } from 'react';
import { WizardData } from '@/App';

interface Props { data: WizardData; update: (p: Partial<WizardData>) => void; onNext: () => void; onBack: () => void; isFirst: boolean; isLast: boolean; }

export function StepAccount({ data, update, onNext, isFirst }: Props) {
  const [errors, setErrors] = useState<Record<string, string>>({});

  function validate() {
    const e: Record<string, string> = {};
    if (!data.email.includes('@')) e.email = 'Enter a valid email address';
    if (data.password.length < 8) e.password = 'Password must be at least 8 characters';
    setErrors(e);
    return Object.keys(e).length === 0;
  }

  return (
    <div className="space-y-5">
      <div>
        <h2 className="text-xl font-bold text-gray-900">Create your account</h2>
        <p className="text-gray-500 text-sm mt-1">We'll get you set up in minutes.</p>
      </div>
      <div className="space-y-4">
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1.5">Email address</label>
          <input type="email" value={data.email} onChange={e => update({ email: e.target.value })} placeholder="you@example.com"
            className={`w-full h-11 px-4 rounded-xl border ${errors.email ? 'border-rose-400 bg-rose-50' : 'border-gray-200'} text-sm focus:outline-none focus:ring-2 focus:ring-violet-500 transition-all`} />
          {errors.email && <p className="text-rose-500 text-xs mt-1">{errors.email}</p>}
        </div>
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1.5">Password</label>
          <input type="password" value={data.password} onChange={e => update({ password: e.target.value })} placeholder="Min. 8 characters"
            className={`w-full h-11 px-4 rounded-xl border ${errors.password ? 'border-rose-400 bg-rose-50' : 'border-gray-200'} text-sm focus:outline-none focus:ring-2 focus:ring-violet-500 transition-all`} />
          {errors.password && <p className="text-rose-500 text-xs mt-1">{errors.password}</p>}
        </div>
      </div>
      <div className="flex justify-end pt-2">
        <button onClick={() => validate() && onNext()} className="h-11 px-8 bg-violet-600 hover:bg-violet-700 text-white text-sm font-semibold rounded-xl transition-colors">Continue →</button>
      </div>
    </div>
  );
}

