"use client";
import { useState } from 'react';
import { WizardData } from '@/App';

interface Props { data: WizardData; update: (p: Partial<WizardData>) => void; onNext: () => void; onBack: () => void; isFirst: boolean; isLast: boolean; }

export function StepProfile({ data, update, onNext, onBack }: Props) {
  const [errors, setErrors] = useState<Record<string, string>>({});

  function validate() {
    const e: Record<string, string> = {};
    if (!data.firstName.trim()) e.firstName = 'First name is required';
    if (!data.lastName.trim()) e.lastName = 'Last name is required';
    setErrors(e);
    return Object.keys(e).length === 0;
  }

  return (
    <div className="space-y-5">
      <div>
        <h2 className="text-xl font-bold text-gray-900">Tell us about yourself</h2>
        <p className="text-gray-500 text-sm mt-1">This is how others will see you.</p>
      </div>
      <div className="space-y-4">
        <div className="grid grid-cols-2 gap-3">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1.5">First name</label>
            <input value={data.firstName} onChange={e => update({ firstName: e.target.value })} placeholder="Jane"
              className={`w-full h-11 px-4 rounded-xl border ${errors.firstName ? 'border-rose-400 bg-rose-50' : 'border-gray-200'} text-sm focus:outline-none focus:ring-2 focus:ring-violet-500 transition-all`} />
            {errors.firstName && <p className="text-rose-500 text-xs mt-1">{errors.firstName}</p>}
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1.5">Last name</label>
            <input value={data.lastName} onChange={e => update({ lastName: e.target.value })} placeholder="Doe"
              className={`w-full h-11 px-4 rounded-xl border ${errors.lastName ? 'border-rose-400 bg-rose-50' : 'border-gray-200'} text-sm focus:outline-none focus:ring-2 focus:ring-violet-500 transition-all`} />
            {errors.lastName && <p className="text-rose-500 text-xs mt-1">{errors.lastName}</p>}
          </div>
        </div>
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1.5">Bio <span className="text-gray-400 font-normal">(optional)</span></label>
          <textarea value={data.bio} onChange={e => update({ bio: e.target.value })} placeholder="A few words about yourself..."
            rows={3} className="w-full px-4 py-3 rounded-xl border border-gray-200 text-sm focus:outline-none focus:ring-2 focus:ring-violet-500 transition-all resize-none" />
        </div>
      </div>
      <div className="flex justify-between pt-2">
        <button onClick={onBack} className="h-11 px-6 border border-gray-200 text-gray-600 hover:bg-gray-50 text-sm font-medium rounded-xl transition-colors">← Back</button>
        <button onClick={() => validate() && onNext()} className="h-11 px-8 bg-violet-600 hover:bg-violet-700 text-white text-sm font-semibold rounded-xl transition-colors">Continue →</button>
      </div>
    </div>
  );
}

