"use client";
import { WizardData } from '@/App';

interface Props { data: WizardData; update: (p: Partial<WizardData>) => void; onNext: () => void; onBack: () => void; isFirst: boolean; isLast: boolean; }

const THEMES = [{ value: 'light', label: 'Light' }, { value: 'dark', label: 'Dark' }, { value: 'system', label: 'System' }];

export function StepPreferences({ data, update, onNext, onBack }: Props) {
  return (
    <div className="space-y-5">
      <div>
        <h2 className="text-xl font-bold text-gray-900">Set your preferences</h2>
        <p className="text-gray-500 text-sm mt-1">Customize your experience.</p>
      </div>
      <div className="space-y-5">
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-3">Theme</label>
          <div className="grid grid-cols-3 gap-3">
            {THEMES.map(t => (
              <button key={t.value} onClick={() => update({ theme: t.value })}
                className={`h-12 rounded-xl border-2 text-sm font-medium transition-all ${
                  data.theme === t.value ? 'border-violet-500 bg-violet-50 text-violet-700' : 'border-gray-200 text-gray-600 hover:border-gray-300'
                }`}>{t.label}</button>
            ))}
          </div>
        </div>
        <div className="flex items-center justify-between p-4 rounded-xl border border-gray-200">
          <div>
            <p className="text-sm font-medium text-gray-900">Email notifications</p>
            <p className="text-xs text-gray-500 mt-0.5">Receive updates and news</p>
          </div>
          <button onClick={() => update({ notifications: !data.notifications })}
            className={`relative w-11 h-6 rounded-full transition-colors ${data.notifications ? 'bg-violet-600' : 'bg-gray-300'}`}>
            <span className={`absolute top-0.5 left-0.5 w-5 h-5 bg-white rounded-full shadow transition-transform ${data.notifications ? 'translate-x-5' : ''}`} />
          </button>
        </div>
      </div>
      <div className="flex justify-between pt-2">
        <button onClick={onBack} className="h-11 px-6 border border-gray-200 text-gray-600 hover:bg-gray-50 text-sm font-medium rounded-xl transition-colors">← Back</button>
        <button onClick={onNext} className="h-11 px-8 bg-violet-600 hover:bg-violet-700 text-white text-sm font-semibold rounded-xl transition-colors">Finish →</button>
      </div>
    </div>
  );
}

